<script setup lang="ts">
import { formatAnalyticsNumber } from "~/lib/analytics-format";
interface Region { id: string; name: string; value: number; code?: string; geometry?: unknown }
const props=withDefaults(defineProps<{regions?:Region[]}>(),{regions:()=>[]}); const emit=defineEmits<{select:[region:Region]}>(); const sorted=computed(()=>[...props.regions].sort((a,b)=>b.value-a.value));
</script>
<template><section class="rounded-xl border bg-muted/20 p-4" aria-labelledby="authoritative-map-title"><div class="mb-3 flex items-center justify-between"><div><h2 id="authoritative-map-title" class="font-bold">Wilayah kabupaten/kota</h2><p class="text-xs text-muted-foreground">Geometri resmi ditampilkan setelah kode dan geometri 27 wilayah lulus readiness.</p></div><NuxtLink to="/dashboard/analitik" class="text-sm font-semibold underline">Buka Analitik</NuxtLink></div><div v-if="regions.length" class="overflow-x-auto"><table class="w-full text-left text-sm"><caption class="sr-only">Sebaran UMKM per wilayah</caption><thead><tr class="border-b"><th class="p-2">Wilayah</th><th class="p-2 text-right">Jumlah UMKM</th><th class="p-2">Tindakan</th></tr></thead><tbody><tr v-for="region in sorted" :key="region.id" class="border-b"><th scope="row" class="p-2">{{ region.name }}</th><td class="p-2 text-right">{{ formatAnalyticsNumber(region.value) }}</td><td class="p-2"><button type="button" class="font-semibold underline" @click="emit('select',region)">Gunakan filter</button></td></tr></tbody></table></div><p v-else class="rounded-md border border-amber-300 bg-amber-50 p-4 text-sm">Peta belum tersedia karena geometri authoritative belum lengkap. Gunakan Analitik dalam bentuk tabel.</p></section></template>
